/*
 * MinerCraft PSP  -  PSP / PSP Go icin voxel madencilik oyunu (PSPSDK / pspgu)
 *
 * KONTROLLER
 *   Analog              : yuru
 *   Ucgen/X/Kare/Daire  : bakis (yukari / asagi / sola / saga)
 *   START               : zipla (suda yuz). Cift basinca ucus (yaratici modda)
 *   SELECT x2 (cift tik): menu ac / kapat
 *   SELECT basili + KARE: eldeki esyayi at
 *   SELECT basili + UCGEN: envanter ac / kapat
 *   L                   : blok koy / yemek ye / etkilesim (calisma masasi, ocak, yatak, makas)
 *   R                   : kir / saldir (basili tut)
 *   D-Pad Sol/Sag       : hotbar sec        D-Pad Yukari: kosu
 *   D-Pad Asagi         : comel (kenardan dusmez) / ucarken alcal
 *   Envanterde KARE     : yigini ikiye bol
 *   Envanterde SELECT + KARE : imlecin ustundeki esyayi at
 *   Hayatta kalma: agac kir -> tahta -> cubuk -> kazma/balta/kurek/kilic (envanter > URETIM)
 *   Comelirken L        : etkilesim yerine blok koyar
 *   Cakmak (demir kulce + cakmak tasi): L ile TNT yak / ates cikar. Ates tahtayi ve yapragi yakar.
 *   Makas (2 demir kulce): L ile koyun kirp, R ile yaprak topla
 *   Yatak (3 yun + 3 tahta): gece uyu; yeniden dogma noktasi olur
 *   Calisma masasi (4 tahta) ve ocak (8 kirma tas) yakininda uretim / eritme yapilir.
 *   Dokular ve envanter ikonlari program acilirken kodla uretilir (ek dosya gerekmez)
 *
 * PERFORMANS
 *   Dunya 16x16x16 bolumlere ayrilir. Yalnizca kameranin gordugu bolumler cizilir ve
 *   mesh'i uretilir; arkada kalan bolumler birkac saniye sonra bellekten silinir.
 */
