/* 0 yapilirsa donanim arka yuz elemesi kapanir */
#define MC_BACKFACE_CULL 1

#define SCR_W 480
#define SCR_H 272
#define BUF_W 512
#define WX 128
#define WY 64
#define WZ 128
#define CS 16
#define NCX (WX / CS)
#define NCZ (WZ / CS)
#define SEA 24
#define PI 3.14159265f
