static void gen_sounds(void) {
    static const float LEN[SN_COUNT] = {0.18f, 0.17f, 0.18f, 0.20f, 0.32f, 0.14f, 0.11f, 0.24f, 0.12f, 0.10f, 0.16f, 0.28f,
        1.30f, 0.90f, 0.07f, 0.60f, 0.30f, 0.70f, 0.20f, 0.40f, 0.25f, 0.035f, 0.18f, 0.28f, 1.20f, TANK_N / (float)SRATE};
    int off = 0;
    for (int id = 0; id < SN_COUNT; id++) {
        int n = (int)(LEN[id] * SRATE);
        if (off + n > SNDMEM) n = SNDMEM - off;
        float lp = 0, lp2 = 0, ph = 0, gate = 1;
        for (int i = 0; i < n; i++) {
            float t = (float)i / SRATE, p = (float)i / n, w = snoise(), s = 0;
            switch (id) {
            case SN_STONE: lp += (w - lp) * 0.40f; s = lp * expf(-t * 24) * 1.3f + sinf(2 * PI * 95 * t) * expf(-t * 35) * 0.4f; break;
            case SN_WOOD:  lp += (w - lp) * 0.25f; ph += (190 - 80 * p) / SRATE; s = (sinf(2 * PI * ph) * 0.7f + lp * 0.7f) * expf(-t * 26); break;
            case SN_GRASS: lp += (w - lp) * 0.16f; s = lp * sinf(PI * p) * (0.6f + 0.4f * sinf(t * 190)) * 1.6f; break;
            case SN_SAND:  if ((i % 90) == 0) gate = 0.25f + fabsf(snoise()); lp += (w - lp) * 0.55f; s = (w - lp) * gate * (1 - p) * 0.7f; break;
            case SN_GLASS: s = (sinf(2 * PI * 2100 * t) + sinf(2 * PI * 3170 * t) * 0.7f + sinf(2 * PI * 4300 * t) * 0.5f) * expf(-t * 15) * 0.3f + w * expf(-t * 60) * 0.6f; break;
            case SN_CLOTH: lp += (w - lp) * 0.07f; s = lp * sinf(PI * p) * 2.2f; break;
            case SN_PLACE: lp += (w - lp) * 0.2f; s = sinf(2 * PI * 135 * t) * expf(-t * 38) * 0.8f + lp * expf(-t * 45); break;
            case SN_HURT:  ph += (340 - 190 * p) / SRATE; lp += ((ph - floorf(ph) < 0.5f ? 0.7f : -0.7f) - lp) * 0.3f; s = lp * (1 - p); break;
            case SN_HIT:   lp += (w - lp) * 0.3f; s = (lp + sinf(2 * PI * 110 * t) * 0.6f) * expf(-t * 30); break;
            case SN_PICK:  ph += (650 + 900 * p) / SRATE; s = sinf(2 * PI * ph) * sinf(PI * p) * 0.5f; break;
            case SN_EAT:   lp += (w - lp) * 0.35f; s = lp * (burst(t, 0, 45) + burst(t, 0.07f, 55) * 0.8f) * 1.2f; break;
            case SN_BURP:  ph += (115 + 25 * sinf(t * 55) - 40 * p) / SRATE; lp += (saw(ph) - lp) * 0.18f; s = lp * sinf(PI * p) * 1.2f; break;
            case SN_BOOM:  lp += (w - lp) * (0.20f - 0.17f * p); lp2 += (lp - lp2) * 0.4f; s = lp2 * expf(-t * 3.0f) * 2.6f + sinf(2 * PI * (62 - 30 * p) * t) * expf(-t * 4) * 0.7f; break;
            case SN_FUSE:  lp += (w - lp) * 0.5f; s = (w - lp) * (0.15f + 0.5f * p) * (p > 0.95f ? (1 - p) * 20 : 1); break;
            case SN_BEEP:  s = sinf(2 * PI * 1250 * t) * (1 - p) * 0.45f; break;
            case SN_BAA: { float vib = 0.65f + 0.35f * sinf(2 * PI * 17 * t); ph += (330 + 12 * sinf(2 * PI * 7 * t) - 45 * p) / SRATE;
                lp += (saw(ph) - lp) * 0.35f; lp2 += (lp - lp2) * 0.06f; s = (lp - lp2) * vib * sinf(PI * p) * 1.1f; break; }
            case SN_OINK:  ph += (165 + 60 * sinf(t * 40)) / SRATE; lp += (saw(ph) * 0.8f + w * 0.35f - lp) * 0.22f;
                s = lp * (p < 0.45f ? sinf(PI * p / 0.45f) : (p > 0.55f ? sinf(PI * (p - 0.55f) / 0.45f) : 0)) * 1.4f; break;
            case SN_GROAN: ph += (96 - 28 * p + 5 * sinf(t * 21)) / SRATE; lp += (saw(ph) + w * 0.15f - lp) * 0.09f; s = lp * sinf(PI * p) * 1.4f; break;
            case SN_SHEAR: lp += (w - lp) * 0.6f; { float e = burst(t, 0, 80) + burst(t, 0.09f, 70); s = ((w - lp) * 0.8f + sinf(2 * PI * 3400 * t) * 0.25f) * e; } break;
            case SN_SPLASH: lp += (w - lp) * (0.45f - 0.35f * p); s = lp * expf(-t * 8) * 1.2f; break;
            case SN_IGNITE: lp += (w - lp) * 0.5f; s = (w - lp) * (burst(t, 0, 90) + 0.35f * burst(t, 0.05f, 12)); break;
            case SN_CLICK: s = sinf(2 * PI * 900 * t) * (1 - p) * 0.35f; break;
            case SN_CRAFT: s = sinf(2 * PI * (p < 0.5f ? 520 : 780) * t) * sinf(PI * fmodf(p * 2, 1.0f)) * 0.45f; break;
            case SN_BREAKTOOL: s = w * expf(-t * 22) * 0.8f + sinf(2 * PI * (420 - 300 * p) * t) * (1 - p) * 0.4f; break;
            case SN_SLEEP: { int k = (int)(p * 3); if (k > 2) k = 2; static const float F[3] = {392, 330, 262};
                float q = p * 3 - k; s = sinf(2 * PI * F[k] * t) * sinf(PI * (q > 1 ? 1 : q)) * 0.35f; } break;
            case SN_TANK: s = tank_ref[i < TANK_N ? i : TANK_N - 1] / 22000.0f; break; /* kullanici kaydi */
            }
            s = clampf(s, -1.0f, 1.0f);
            if (i >= n - 32) s *= (n - i) / 32.0f; /* sonda tik sesi olmasin */
            sndmem[off + i] = (short)(s * 22000.0f);
        }
        snds[id].off = off; snds[id].len = n;
        off += n;
    }
}
static void init_audio(void) {
    gen_sounds();
    audioCh = sceAudioChReserve(PSP_AUDIO_NEXT_CHANNEL, ASAMP, PSP_AUDIO_FORMAT_STEREO);
    if (audioCh < 0) return;
    int t = sceKernelCreateThread("audio_mix", audio_thread, 0x12, 0x4000, THREAD_ATTR_USER, 0);
    if (t >= 0) sceKernelStartThread(t, 0, 0);
}
/* vol 0..1, pan -1 (sol) .. 1 (sag) */
static void snd_pan(int id, float vol, float pitch, float pan) {
    vol *= sndVol / 5.0f;
    if (vol < 0.02f) return;
    for (int k = 0; k < NVOICE; k++) {
        Voice *v = &voices[k];
        if (v->on) continue;
        v->d = sndmem + snds[id].off;
        v->pos = 0;
        v->end = (u32)snds[id].len << 16;
        v->step = (u32)(pitch * (SRATE / 44100.0f) * 65536.0f);
        v->vl = (int)(256 * vol * clampf(1.0f - pan, 0, 1));
        v->vr = (int)(256 * vol * clampf(1.0f + pan, 0, 1));
        __asm__ volatile("" ::: "memory");
        v->on = 1;
        return;
    }
}
static void snd(int id, float vol, float pitch) { snd_pan(id, vol, pitch, 0); }

