#define PAL_COLS 12
#define REC_ROWS 6
static void rec_part(int x, int y, u8 id, int n, int ok) {
    Slot sl = {id, 1, 0};
    slot_draw(x, y, 28, &sl, 0, 0);
    char b[8]; snprintf(b, sizeof(b), "%d", n);
    ptext(x + 32, y + 9, 2, ok ? 0xFFFFFFFF : 0xFF6666FF, b);
}
static void draw_recipes(int station) {
    char b[96];
    int r0 = recCur - REC_ROWS / 2;
    if (r0 > nrl - REC_ROWS) r0 = nrl - REC_ROWS;
    if (r0 < 0) r0 = 0;
    int bench = station == 1 || st_ok(1), furn = station == 2 || st_ok(2), free_ = mode == 0;
    for (int i = r0; i < r0 + REC_ROWS && i < nrl; i++) {
        const Rec *r = &REC[rlist[i]];
        int ha = free_ || count_item(r->a) >= r->an, hb = free_ || !r->b || count_item(r->b) >= r->bn;
        int sok = free_ || r->st == 0 || (r->st == 1 ? bench : furn);
        int y = 38 + (i - r0) * 31;
        rect(26, y - 1, 428, 30, i == recCur ? RGBA(255, 255, 255, 65) : RGBA(255, 255, 255, 16));
        rec_part(30, y, r->a, r->an, ha);
        if (r->b) { ptext(84, y + 9, 2, 0xFFAAAAAA, "+"); rec_part(98, y, r->b, r->bn, hb); }
        ptext(150, y + 9, 2, 0xFFAAAAAA, ">");
        rec_part(166, y, r->out, r->on, 1);
        u32 col = (ha && hb && sok) ? 0xFF55FF55 : ((ha && hb) ? 0xFF3399FF : 0xFF9999AA);
        ptext(224, y + 4, 2, col, BI[r->out].n);
        if (r->st && !station) ptext(224, y + 19, 1, sok ? 0xFFAAAAAA : 0xFF3399FF, r->st == 1 ? "CALISMA MASASI" : "OCAK");
    }
    const Rec *r = &REC[rlist[recCur]];
    if (free_) snprintf(b, sizeof(b), "YARATICI MOD: URETIM BEDAVA");
    else if (r->b) snprintf(b, sizeof(b), "SENDE: %s %d/%d   %s %d/%d", BI[r->a].n, count_item(r->a), r->an, BI[r->b].n, count_item(r->b), r->bn);
    else snprintf(b, sizeof(b), "SENDE: %s %d/%d", BI[r->a].n, count_item(r->a), r->an);
    ctext(SCR_W / 2, 232, 1, 0xFFFFFFFF, b);
    snprintf(b, sizeof(b), "TARIF %d / %d", recCur + 1, nrl);
    ctext(SCR_W / 2, 248, 1, 0xFF888888, b);
}
